<section class="mx-auto max-w-3xl space-y-6"><x-app.page-header :title="$group->name.' agreements'" /><flux:card class="space-y-3"><form wire:submit="create" class="space-y-3"><flux:input wire:model="name" label="Agreement name" /><flux:textarea wire:model="content" label="Initial version" rows="5" /><flux:checkbox wire:model="required" label="Required for admission" /><flux:button type="submit" variant="primary">Create agreement</flux:button></form></flux:card>@foreach($agreements as $agreement)<flux:card class="space-y-3"><flux:heading>{{ $agreement->name }}</flux:heading>@foreach($agreement->versions as $version)<div class="flex flex-col gap-2 border-b pb-2 sm:flex-row sm:justify-between"><flux:text>v{{ $version->version }} · {{ $version->status }}</flux:text>@if(!in_array($version->status, ['active','superseded']))<flux:button wire:click="activate({{ $version->id }})" size="sm">Activate</flux:button>@endif</div>@endforeach <div class="flex flex-col gap-2 sm:flex-row"><flux:textarea wire:model="content" aria-label="Revision content" rows="2" /><flux:button wire:click="revise({{ $agreement->id }})">Create revision</flux:button></div></flux:card>@endforeach</section>
